SOURCE_INPUTS={'rack': {'asset_id': 'carpentry-a-frame-sheet-storage-rack-kit-01', 'sha256': '0db9befbbe4b4dfdaf4282dcbc7a00aafcdaa96ef1fd2ace193f7a811e6b48db', 'compressed': ''}, 'crate': {'asset_id': 'transport-three-slot-panel-cargo-crate-01', 'sha256': '3d55f8dbc1aa5236159a3c871b9dc5beaea380b20d0b3382a61f5e98b19d9374', 'compressed': ''}, 'pallet': {'asset_id': 'logistics-wood-pallet-01', 'sha256': 'aef803468d2fb4c3ed604a27b234a98e0ec50299041eeac0b181ded02f8d7715', 'compressed': ''}}
